139	function readFromCache<T extends object>(cachePath: string): T {
140	  try {
141	    return process.env.NX_CACHE_PROJECT_GRAPH !== 'false'
142	      ? readJsonFile<T>(cachePath)
143	      : ({} as T);
144	  } catch {
145	    return {} as T;
