148	function readTsConfigCacheData(): Record<string, TsconfigCacheData> {
149	  const cache = readFromCache<TsconfigCache>(TS_CONFIG_CACHE_PATH);
150	
151	  if (cache.version !== TSCONFIG_CACHE_VERSION) {
152	    return {};
153	  }
154	
155	  return cache.data;
156	}
