ccessor so the substitution manager always sees\n    // the current nameMap without manual synchronization.\n    this.nameSubstitutionManager = new ProjectNameInNodePropsManager(\n      () => this.nameMap\n    );\n  }\n\n  getRootMap(): Record<string, ProjectConfiguration> {\n    return this.rootMap;\n  }\n\n  /**\n   * Merges a project into the rootMap, updates the nameMap, and notifies\n   * the substitution manager if the name changed at this root.\n   */\n  mergeProjectNode(\n    project: ProjectConfiguration,\n    configurationSourceMaps?: ConfigurationSourceMaps,\n    sourceInformation?: SourceInformation\n  ): void {\n    const previousName = this.rootMap[project.root]?.name;\n\n    mergeProjectConfigurationIntoRootMap(\n      this.rootMap,\n      project,\n      configurationSourceMaps,\n      sourceInformation\n    );\n\n    const merged = this.rootMap[project.root];\n    const currentName = merged?.name;\n\n    if (currentName) {\n      // Remove old nameMap entry on rename\n      if (previousName && previousName !== currentName) {\n        delete this.nameMap[previousName];\n      }\n      // Point nameMap at the same object as rootMap\n      this.nameMap[currentName] = merged;\n\n      // Notify substitution manager of name change\n      if (currentName !== previousName) {\n        this.nameSubstitutionManager.identifyProjectWithRoot(\n          project.root,\n          currentName\n        );\n      }\n    }\n  }\n\n  /**\n   * Registers substitutors for a plugin result's project references\n   * in `inputs` and `dependsOn`.\n   */\n  registerSubstitutors(\n    pluginResultProjects?: Record<\n      string,\n      Omit<ProjectConfiguration, 'root'> & Partial<ProjectConfiguration>\n    >\n  ): void {\n    this.nameSubstitutionManager.registerSubstitutorsForNodeResults(\n      pluginResultProjects\n    );\n  }\n\n  /**\n   * Applies all pending name substitutions. Call once after all plugin\n   * results have been merged.\n   */\n  applySubstitutions(): void {\n    this.nameSubstitutionManager.applySubstitutions(this.rootMap);\n  }\n}\n"],"names":["ProjectNodesManager","createRootMap","mergeProjectConfigurationIntoRootMap","readProjectConfigurationsFromRootMap","validateProject","projectRootMap","project","configurationSourceMaps","sourceInformation","skipTargetNormalization","root","sourceMap","matchingProject","updatedProjectConfiguration","k","includes","tags","Array","from","Set","concat","forEach","tag","implicitDependencies","implicitDependency","generators","generator","property","namedInputs","namedInput","metadata","mergeMetadata","targets","targetName","target","targetSourceMapKey","normalizedTarget","resolveCommandSyntacticSugar","matchingTargets","isGlobPattern","Object","keys","filter","key","minimatch","length","matchingTargetName","mergeTargetConfigurations","nameChanged","name","projects","conflicts","Map","projectRootsWithNoName","e","isProjectWithNoNameError","push","projectRoot","isProjectWithExistingNameError","rootErrors","get","projectName","set","size","MultipleProjectsWithSameNameError","ProjectsWithNoNameError","map","rootMap","nameMap","nameSubstitutionManager","ProjectNameInNodePropsManager","getRootMap","mergeProjectNode","previousName","merged","currentName","identifyProjectWithRoot","registerSubstitutors","pluginResultProjects","registerSubstitutorsForNodeResults","applySubstitutions"],"mappings":";;;;4BAMO;+BAKA;qCACyB;yCACc;4BAEX;2BAET;uBACI;+BAoQjBA;;;eAAAA;;;QAAAA;;;;+BApBGC;;;eAAAA;;;QAAAA;;;;+BA5OAC;;;eAAAA;;;QAAAA;;;;+BAiMAC;;;eAAAA;;;QAAAA;;;;+BAnMPC;;;;;;;;;;AAEF,SAASF,qCACdG,cAAoD,EACpDC,OAA6B,EAC7BC,uBAAiD,EACjDC,iBAAqC,EACrC,2DAA2D;AAC3D,iDAAiD;AACjDC,uBAAiC;IAIjCH,QAAQI,IAAI,GAAGJ,QAAQI,IAAI,KAAK,KAAK,MAAMJ,QAAQI,IAAI;IACvD,IAAIH,2BAA2B,CAACA,uBAAuB,CAACD,QAAQI,IAAI,CAAC,EAAE;QACrEH,uBAAuB,CAACD,QAAQI,IAAI,CAAC,GAAG,CAAC;IAC3C;IACA,MAAMC,YAAYJ,yBAAyB,CAACD,QAAQI,IAAI,CAAC;IAEzD,IAAIE,kBAAkBP,cAAc,CAACC,QAAQI,IAAI,CAAC;IAElD,IAAI,CAACE,iBAAiB;QACpBP,cAAc,CAACC,QAAQI,IAAI,CAAC