+{"version":3,"sources":["/workspace/repo/packages/nx/src/utils/print-help.ts"],"sourcesContent":["import * as pc from 'picocolors';\nimport stringWidth from 'string-width';\nimport { logger } from './logger';\nimport { output } from './output';\nimport { Schema } from './params';\nimport { nxVersion } from './versions';\nimport { readModulePackageJson } from './package-json';\n\n// cliui is the CLI layout engine developed by, and used within, yargs\n// the typings for cliui do not play nice with our tsconfig, it either\n// works in build or in test but not both.\nconst cliui = require('cliui') as (typeof import('cliui'))['default'];\n\nexport function printHelp(\n  header: string,\n  schema: Schema,\n  meta:\n    | { mode: 'generate'; plugin: string; entity: string; aliases: string[] }\n    | { mode: 'run'; plugin: string; entity: string }\n) {\n  const allPositional = Object.keys(schema.properties).filter((key) => {\n    const p = schema.properties[key];\n    return p['$default'] && p['$default']['$source'] === 'argv';\n  });\n  const positional = allPositional.length > 0 ? ` [${allPositional[0]}]` : '';\n\n  logger.info(`\n${output.applyNxPrefix(\n  'cyan',\n  pc.bold(`${`${header + pc.cyan(positional)} ${pc.cyan('[options,...]')}`}`)\n)}\n\n${generateOverviewOutput({\n  pluginName: meta.plugin,\n  name: meta.entity,\n  description: schema.description,\n  mode: meta.mode,\n  aliases: meta.mode === 'generate' ? meta.aliases : [],\n})}\n${generateOptionsOutput(schema)}\n${generateExamplesOutput(schema)}\n${generateLinkOutput({\n  pluginName: meta.plugin,\n  name: meta.entity,\n  type: meta.mode === 'generate' ? 'generators' : 'executors',\n})}\n`);\n}\n\nfunction generateOverviewOutput({\n  pluginName,\n  name,\n  description,\n  mode,\n  aliases,\n}: {\n  pluginName: string;\n  name: string;\n  description: string;\n  mode: 'generate' | 'run';\n  aliases: string[];\n}): string {\n  switch (mode) {\n    case 'generate':\n      return generateGeneratorOverviewOutput({\n        pluginName,\n        name,\n        description,\n        aliases,\n      });\n    case 'run':\n      return generateExecutorOverviewOutput({\n        pluginName,\n        name,\n        description,\n      });\n    default:\n      throw new Error(`Unexpected mode ${mode}`);\n  }\n}\n\nfunction generateGeneratorOverviewOutput({\n  pluginName,\n  name,\n  description,\n  aliases,\n}: {\n  pluginName: string;\n  name: string;\n  description: string;\n  aliases: string[];\n}): string {\n  const ui = cliui(null);\n  const overviewItemsLabelWidth =\n    // Chars in labels \"From\" and \"Name\"\n    4 +\n    // The `:` char\n    1;\n\n  let installedVersion: string;\n  try {\n    installedVersion = readModulePackageJson(pluginName).packageJson.version;\n  } catch {}\n\n  ui.div(\n    ...[\n      {\n        text: pc.bold('From:'),\n        padding: [1, 0, 0, 0],\n        width: overviewItemsLabelWidth,\n      },\n      {\n        text:\n          pluginName +\n          (installedVersion ? pc.dim(` (v${installedVersion})`) : ''),\n        padding: [1, 0, 0, 2],\n      },\n    ]\n  );\n\n  ui.div(\n    ...[\n      {\n        text: pc.bold('Name:'),\n        padding: [0, 0, 0, 0],\n        width: overviewItemsLabelWidth,\n      },\n      {\n        text: `${name}${\n          aliases.length ? pc.dim(` (aliases: ${aliases.join(', ')})`) : ''\n        }`,\n        padding: [0, 0, 0, 2],\n      },\n    ]\n  );\n\n  ui.div(\n    ...[\n      {\n        text: description,\n        padding: [2, 0, 1, 2],\n      },\n    ]\n  );\n\n  return ui.toString();\n}\n\nfunction generateExecutorOverviewOutput({\n  pluginName,\n  name,\n  description,\n}: {\n  pluginName: string;\n  name: string;\n  description: string;\n}): string {\n  const ui = cliui(null);\n  const overviewItemsLeftPadding = 2;\n  const overviewItemsLabelWidth = overviewItemsLeftPadding + 'Executor:'.length;\n\n  ui.div(\n    ...[\n      {\n        text: pc.bold('Executor:'),\n        padding: [1, 0, 0, 0],\n        width: overviewItemsLabelWidth,\n      },\n      {\n        text:\n          `${pluginName}:${name}` +\n          (pluginName.startsWith('@nx/') ? pc.dim(` (v${nxVersion})`) : ''),\n        padding: [1, 0, 0, 0],\n      },\n    ]\n  );\n\n  ui.div(\n    ...[\n      {\n        text: description,\n        padding: [2, 0, 1, 2],\n      },\n    ]\n  );\n\n  return ui.toString();\n}\n\nconst formatOptionVal = (maybeStr: unknown) =>\n  typeof maybeStr === 'string' ? `\"${maybeStr}\"` : JSON.stringify(maybeStr);\n\n// From our JSON schemas an option could possibly have more than one valid type\nconst formatOptionType = (optionConfig: Schema['properties'][0]) => {\n  if (Array.isArray(optionConfig.oneOf)) {\n    return optionConfig.oneOf\n      .map((typeConfig) => formatOptionType(typeConfig))\n      .join(' OR ');\n  }\n  return `[${optionConfig.type}]`;\n};\n\nfunction generateOptionsOutput(schema: Schema): string {\n  const ui = cliui(null);\n  const flagAndAliasLeftPadding = 4;\n  const flagAndAliasRightPadding = 4;\n\n  // Construct option flags (including optional aliases) and descriptions and track the required space to render them\n  const optionsToRender = new Map<\n    string,\n    {\n      renderedFlagAndAlias: string;\n      renderedDescription: string;\n      renderedTypesAndDefault: string;\n    }\n  >();\n  let requiredSpaceToRenderAllFlagsAndAliases = 0;\n  const sorted = Object.entries(schema.properties).sort((a, b) =>\n    compareByPriority(a, b, schema)\n  );\n  for (const [optionName, optionConfig] of sorted) {\n    const renderedFlagAndAlias =\n      `--${optionName}` +\n      (optionConfig.alias ? `, -${optionConfig.alias}` : '');\n\n    const renderedFlagAndAliasTrueWidth = stringWidth(renderedFlagAndAlias);\n    if (\n      renderedFlagAndAliasTrueWidth > requiredSpaceToRenderAllFlagsAndAliases\n    ) {\n      requiredSpaceToRenderAllFlagsAndAliases = renderedFlagAndAliasTrueWidth;\n    }\n\n    const renderedDescription = optionConfig.description;\n    const renderedTypesAndDefault = `${formatOptionType(optionConfig)}${\n      optionConfig.enum\n        ? ` [choices: ${optionConfig.enum\n            .map((e) => formatOptionVal(e))\n            .join(', ')}]`\n        : ''\n    }${\n      optionConfig.default\n        ? ` [default: ${formatOptionVal(optionConfig.default)}]`\n        : ''\n    }`;\n\n    optionConfig.hidden ??= optionConfig.visible === false;\n    if (!optionConfig.hidden)\n      optionsToRender.set(optionName, {\n        renderedFlagAndAlias,\n        renderedDescription,\n        renderedTypesAndDefault,\n      });\n  }\n\n  ui.div({\n    text: 'Options:',\n    padding: [1, 0, 0, 0],\n  });\n\n  for (const {\n    renderedFlagAndAlias,\n    renderedDescription,\n    renderedTypesAndDefault,\n  } of optionsToRender.values()) {\n    const cols = [\n      {\n        text: renderedFlagAndAlias,\n        width:\n          requiredSpaceToRenderAllFlagsAndAliases +\n          flagAndAliasLeftPadding +\n          flagAndAliasRightPadding,\n        padding: [0, flagAndAliasRightPadding, 0, flagAndAliasLeftPadding],\n      },\n      {\n        text: renderedDescription,\n        padding: [0, 0, 0, 0],\n      },\n      {\n        text: renderedTypesAndDefault,\n        padding: [0, 0, 0, 0],\n        align: 'right' as const,\n      },\n    ];\n\n    ui.div(...cols);\n  }\n\n  return ui.toString();\n}\n\nfunction generateExamplesOutput(schema: Schema): string {\n  if (!schema.examples || schema.examples.length === 0) {\n    return '';\n  }\n  const ui = cliui(null);\n  const xPadding = 4;\n\n  ui.div({\n    text: 'Examples:',\n    padding: [1, 0, 0, 0],\n  });\n\n  for (const { command, description } of schema.examples) {\n    const cols = [\n      {\n        text: command,\n        padding: [0, xPadding, 0, xPadding],\n      },\n      {\n        text: description || '',\n        padding: [0, 2, 0, 0],\n      },\n    ];\n\n    ui.div(...cols);\n  }\n\n  return ui.toString();\n}\n\n// TODO: generalize link generation so it works for non @nx plugins as well\nfunction generateLinkOutput({\n  pluginName,\n  name,\n  type,\n}: {\n  pluginName: string;\n  name: string;\n  type: 'generators' | 'executors';\n}): string {\n  const nxPackagePrefix = '@nx/';\n  if (!pluginName.startsWith(nxPackagePrefix)) {\n    return '';\n  }\n\n  const link = `https://nx.dev/nx-api/${pluginName.substring(\n    nxPackagePrefix.length\n  )}/${type}/${name}`;\n\n  return `\\n\\n${pc.dim(\n    'Find more information and examples at:'\n  )} ${pc.bold(link)}`;\n}\n\n/**\n * sorts properties in the following order\n * - required\n * - x-priority: important\n * - everything else\n * - x-priority: internal\n * - deprecated\n * if two properties have equal priority, they are sorted by name\n */\nfunction compareByPriority(\n  a: [string, Schema['properties'][0]],\n  b: [string, Schema['properties'][0]],\n  schema: Schema\n): number {\n  function getPriority([name, property]: [\n    string,\n    Schema['properties'][0],\n  ]): number {\n    if (schema.required?.includes(name)) {\n      return 0;\n    }\n    if (property['x-priority'] === 'important') {\n      return 1;\n    }\n    if (property['x-deprecated']) {\n      return 4;\n    }\n    if (property['x-priority'] === 'internal') {\n      return 3;\n    }\n    return 2;\n  }\n\n  const aPriority = getPriority(a);\n  const bPriority = getPriority(b);\n  if (aPriority === bPriority) {\n    return a[0].localeCompare(b[0]);\n  }\n  return aPriority - bPriority;\n}\n"],"names":["printHelp","cliui","require","header","schema","meta","allPositional","Object","keys","properties","filter","key","p","positional","length","logger","info","output","applyNxPrefix","pc","bold","cyan","generateOverviewOutput","pluginName","plugin","name","entity","description","mode","aliases","generateOptionsOutput","generateExamplesOutput","generateLinkOutput","type","generateGeneratorOverviewOutput","generateExecutorOverviewOutput","Error","ui","overviewItemsLabelWidth","installedVersion","readModulePackageJson","packageJson","version","div","text","padding","width","dim","join","toString","overviewItemsLeftPadding","startsWith","nxVersion","formatOptionVal","maybeStr","JSON","stringify","formatOptionType","optionConfig","Array","isArray","oneOf","map","typeConfig","flagAndAliasLeftPadding","flagAndAliasRightPadding","optionsToRender","Map","requiredSpaceToRenderAllFlagsAndAliases","sorted","entries","sort","a","b","compareByPriority","optionName","renderedFlagAndAlias","alias","renderedFlagAndAliasTrueWidth","stringWidth","renderedDescription","renderedTypesAndDefault","enum","e","default","hidden","visible","set","values","cols","align","examples","xPadding","command","nxPackagePrefix","link","substring","getPriority","property","required","includes","aPriority","bPriority","localeCompare"],"mappings":";;;;oEAAoB;oEACI;wBACD;wBACA;0BAEG;6BACY;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;+BAOtBA;;;eAAAA;;;QAAAA;;;;AALhB,sEAAsE;AACtE,sEAAsE;AACtE,0CAA0C;AAC1C,MAAMC,QAAQC,QAAQ;AAEf,SAASF,UACdG,MAAc,EACdC,MAAc,EACdC,IAEmD;IAEnD,MAAMC,gBAAgBC,OAAOC,IAAI,CAACJ,OAAOK,UAAU,EAAEC,MAAM,CAAC,CAACC;QAC3D,MAAMC,IAAIR,OAAOK,UAAU,CAACE,IAAI;QAChC,OAAOC,CAAC,CAAC,WAAW,IAAIA,CAAC,CAAC,WAAW,CAAC,UAAU,KAAK;IACvD;IACA,MAAMC,aAAaP,cAAcQ,MAAM,GAAG,IAAI,CAAC,EAAE,EAAER,aAAa,CAAC,EAAE,CAAC,CAAC,CAAC,GAAG;IAEzES,cAAM,CAACC,IAAI,CAAC,CAAC;AACf,EAAEC,cAAM,CAACC,aAAa,CACpB,QACAC,YAAGC,IAAI,CAAC,GAAG,GAAGjB,SAASgB,YAAGE,IAAI,CAACR,YAAY,CAAC,EAAEM,YAAGE,IAAI,CAAC,kBAAkB,EAAE,GAC1E;;AAEF,EAAEC,uBAAuB;QACvBC,YAAYlB,KAAKmB,MAAM;QACvBC,MAAMpB,KAAKqB,MAAM;QACjBC,aAAavB,OAAOuB,WAAW;QAC/BC,MAAMvB,KAAKuB,IAAI;QACfC,SAASxB,KAAKuB,IAAI,KAAK,aAAavB,KAAKwB,OAAO,GAAG,EAAE;IACvD,GAAG;AACH,EAAEC,sBAAsB1B,QAAQ;AAChC,EAAE2B,uBAAuB3B,QAAQ;AACjC,EAAE4B,mBAAmB;QACnBT,YAAYlB,KAAKmB,MAAM;QACvBC,MAAMpB,KAAKqB,MAAM;QACjBO,MAAM5B,KAAKuB,IAAI,KAAK,aAAa,eAAe;IAClD,GAAG;AACH,CAAC;AACD;AAEA,SAASN,uBAAuB,EAC9BC,UAAU,EACVE,IAAI,EACJE,WAAW,EACXC,IAAI,EACJC,OAAO,EAOR;IACC,OAAQD;QACN,KAAK;YA